'use client'
import { useEffect, useState, useCallback } from 'react'
import { createClient } from '@/lib/supabase'
import { fetchAll as fetchAllPages } from '@/lib/fetchAll'
import { usePermissions } from '@/lib/permissions'

const C={darkGreen:'#1a4d2e',midGreen:'#2d6a4f',accent:'#39b54a',white:'#ffffff',dark:'#0d1f14',gray:'#6b7c72',lightGray:'#e8ede9',red:'#e53e3e',amber:'#d97706',blue:'#2563eb',purple:'#7c3aed'}
const fmt=(n:number)=>`₱${Number(n||0).toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2})}`
const UNIT_OPTIONS = ['PCS', 'LOT', 'SET', 'KG', 'M', 'FT', 'ROLL', 'BOX', 'UNIT']
const OFFICIAL_HEADER_URI = 'data:image/png;base64,'

function printSupplierPO(order:any, supplier:any, preparedBy?:string) {
  const items = order.purchase_order_items||[]
  const subtotal = items.reduce((s:number,i:any)=>s+Number(i.qty)*Number(i.unit_price),0)
  // EWT (1% expanded withholding tax) computed on the VAT-exclusive base,
  // matching the reference template exactly: subtotal / 1.12 * 1% = subtotal/112.
  const ewt = subtotal / 112
  const grandTotal = subtotal - ewt
  const today = new Date().toISOString().slice(0,10)
  const w = window.open('', '_blank', 'width=950,height=750')
  if (!w) return
  w.document.write(`<html><head><title>Purchase Order – ${order.id}</title>
  <style>*{margin:0;padding:0;box-sizing:border-box;font-family:Arial,sans-serif;font-size:12px;-webkit-print-color-adjust:exact;print-color-adjust:exact;color-adjust:exact}
  @media print{*{-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important;color-adjust:exact!important}}
  body{padding:36px;color:#111}
  .top{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:6px}
  .brand img{width:340px;height:auto}
  .infobox{text-align:right}
  .infobox div{font-size:12px;margin-bottom:2px}
  .infobox b{display:inline-block;min-width:120px;text-align:left}
  .twocol{display:flex;gap:24px;margin-top:22px}
  .ordbox{flex:1;border:1px solid #000}
  .ordbox .hd{background:#0d1f14;color:#fff;font-weight:800;padding:4px 8px;font-size:11px;letter-spacing:1px}
  .ordbox .row{display:flex;border-top:1px solid #000}
  .ordbox .row span:first-child{width:130px;font-weight:700;padding:5px 8px;border-right:1px solid #000;background:#f4f7f5}
  .ordbox .row span:last-child{flex:1;padding:5px 8px}
  table.items{width:100%;border-collapse:collapse;margin-top:18px;border:1px solid #000}
  table.items thead th{background:#8dc63f;border:1px solid #000;padding:5px 8px;font-size:10px;text-transform:uppercase;letter-spacing:0.5px}
  table.items td{border-left:1px solid #000;border-right:1px solid #000;padding:6px 8px;vertical-align:top}
  table.items tr{border-bottom:1px solid #ccc}
  .attn-row td{border-top:none;font-style:italic;color:#333;padding-top:4px;padding-bottom:8px}
  .totbox{width:280px;margin-left:auto;margin-top:12px;border:1px solid #000}
  .totbox div{display:flex;justify-content:space-between;padding:4px 10px;border-bottom:1px solid #000}
  .totbox div.grand{background:#8dc63f;font-weight:900;font-size:13px;border-bottom:none}
  .closing{margin-top:20px;font-size:11px}
  .sign{margin-top:46px;font-size:11px}
  .sign .name{font-weight:900;border-top:1px solid #000;display:inline-block;padding-top:4px;margin-top:44px}
  .sign .title{color:#555;margin-top:2px}
  </style></head><body>
  <div class="top">
    <div class="brand"><img src="${OFFICIAL_HEADER_URI}"/></div>
    <div class="infobox">
      <div><b>Date:</b> ${today}</div>
      <div><b>Purchase Order:</b> ${order.id}</div>
      <div><b>Payment Terms:</b> ${order.payment_terms||'Cash On Delivery'}</div>
    </div>
  </div>

  <div class="twocol">
    <div class="ordbox">
      <div class="hd">ORDER TO:</div>
      <div class="row"><span>COMPANY NAME:</span><span>${supplier?.name||''}</span></div>
      <div class="row"><span>ADDRESS:</span><span>${supplier?.address||''}</span></div>
    </div>
    <div class="ordbox">
      <div class="hd">SHIP TO:</div>
      <div class="row"><span>COMPANY NAME:</span><span>GEMMN ENGINEERING WORKS</span></div>
      <div class="row"><span>ADDRESS:</span><span>#55 Warehouse #8, Mighty Corporation Compound, Mighty Road, Barangay Tikay, City of Malolos, Bulacan</span></div>
    </div>
  </div>

  <table class="items">
    <thead><tr><th style="width:6%">ITEM#</th><th style="width:32%">DESCRIPTION</th><th style="width:13%">DELIVERY DATE</th><th style="width:8%">QTY</th><th style="width:8%">UNIT</th><th style="width:15%">UNIT PRICE</th><th style="width:18%">LINE TOTAL</th></tr></thead>
    <tbody>
      ${supplier?.contact_person ? `<tr class="attn-row"><td colspan="7">ATTN: ${supplier.contact_person}</td></tr>` : ''}
      ${items.map((item:any,idx:number)=>`
      <tr>
        <td>${idx+1}</td>
        <td>${item.material_name||''}${item.dimension?` (${item.dimension})`:''}</td>
        <td>${order.expected_delivery||'—'}</td>
        <td>${item.qty}</td>
        <td>${item.unit||''}</td>
        <td>${fmt(item.unit_price)}</td>
        <td>${fmt(Number(item.qty)*Number(item.unit_price))}</td>
      </tr>`).join('')}
    </tbody>
  </table>

  <div class="totbox">
    <div><span>SUBTOTAL:</span><span>${fmt(subtotal)}</span></div>
    <div><span>EWT:</span><span>${fmt(ewt)}</span></div>
    <div class="grand"><span>GRAND TOTAL:</span><span>${fmt(grandTotal)}</span></div>
  </div>

  <div class="closing">Thank you very much. If you have any questions or concern about this purchase order, please contact ${preparedBy||'the undersigned'}.</div>

  <div class="sign">
    <div>Very Truly Yours,</div>
    <div class="name">${preparedBy||'Authorized Representative'}</div>
    <div class="title">GEMMN Engineering Works</div>
  </div>
  </body></html>`)
  w.document.close(); w.focus(); setTimeout(() => { w.print(); w.close() }, 400)
}
const inputStyle:React.CSSProperties={width:'100%',padding:'9px 12px',border:'1.5px solid #e8ede9',borderRadius:6,fontSize:13,fontFamily:'inherit',color:'#0d1f14',background:'#fafcfb',boxSizing:'border-box',outline:'none'}

function Field({label,type='text',value,onChange,options,placeholder,span,disabled}:any){
  const lbl=(label||'').toLowerCase()
  const skipUppercase=/notes|remarks|description|terms|comment|email|password/.test(lbl)
  const skipDefault=/supplier name|material name/.test(lbl)
  return(
    <div style={{marginBottom:14,gridColumn:span?'1/-1':'auto'}}>
      <label style={{fontSize:10,fontWeight:800,letterSpacing:1.5,color:C.gray,textTransform:'uppercase',display:'block',marginBottom:5}}>{label}</label>
      {type==='select'
        ?<select value={value} onChange={e=>onChange(e.target.value)} style={inputStyle} disabled={disabled}><option value="">Select…</option>{(options||[]).map((o:any)=><option key={o.value??o} value={o.value??o}>{o.label??o}</option>)}</select>
        :<input type={type} value={value} onChange={e=>onChange(type==='number'||skipUppercase?e.target.value:e.target.value.toUpperCase())} onFocus={e=>e.target.select()} onBlur={e=>{if(type==='number'){if(!e.target.value.trim())onChange('0')}else if(!skipDefault&&!e.target.value.trim())onChange('N/A')}} style={{...inputStyle,background:disabled?'#f4f7f5':inputStyle.background}} disabled={disabled}/>}
    </div>
  )
}

const REQUEST_STATUSES = ['Pending Quotes','Comparing','Approved','PO Released','Fulfilled','Cancelled']

export default function PurchasingPage(){
  const supabase=createClient()
  const perms = usePermissions()
  const canEdit = perms.canEditModule('purchasing')
  const fullAccess = perms.fullAccess
  const [currentUserName, setCurrentUserName] = useState('')
  useEffect(() => {
    supabase.auth.getUser().then(async ({ data: { user } }) => {
      if (!user) return
      const { data } = await supabase.from('profiles').select('full_name').eq('id', user.id).single()
      setCurrentUserName(data?.full_name || user.email || '')
    })
  }, [])
  const [tab,setTab]=useState<'requests'|'suppliers'|'orders'>('requests')
  const [loading,setLoading]=useState(true)
  const [error,setError]=useState('')
  const [saving,setSaving]=useState(false)
  // Pagination — bulk historical import left both Material Requests and
  // Purchase Orders too long to scroll comfortably; Suppliers stays a short
  // reference list and doesn't need it.
  const [reqPage,setReqPage]=useState(1)
  const [quotePoMap,setQuotePoMap]=useState<Record<string,string>>({})
  const [orderPage,setOrderPage]=useState(1)
  const PAGE_SIZE = 50

  // ── Data ──────────────────────────────────────────────────────────────────
  const [suppliers,setSuppliers]=useState<any[]>([])
  const [supplierMaterials,setSupplierMaterials]=useState<any[]>([])
  const [requests,setRequests]=useState<any[]>([])
  const [quotes,setQuotes]=useState<any[]>([])
  const [orders,setOrders]=useState<any[]>([])
  const [receipts,setReceipts]=useState<any[]>([])
  const [invoices,setInvoices]=useState<any[]>([])
  const [inventoryItems,setInventoryItems]=useState<any[]>([])
  const [approvalThreshold,setApprovalThreshold]=useState(20000)
  useEffect(()=>{ supabase.from('app_settings').select('value').eq('key','po_approval_threshold').single().then(({data})=>{ if(data) setApprovalThreshold(Number(data.value)) }) },[])

  const fetchAll = useCallback(async()=>{
    setLoading(true)
    const [
      {data:sup},{data:supMat},{data:reqs},{data:qts},{data:ords},{data:recs},{data:invs},{data:inv},{data:quoPos}
    ] = await Promise.all([
      supabase.from('suppliers').select('*').order('name'),
      supabase.from('supplier_materials').select('*').order('material_name'),
      // Comment above already notes a bulk historical import pushed these two
      // tables past comfortable scroll length — that same import can also push
      // them past PostgREST's silent default 1000-row cap, so range explicitly.
      fetchAllPages<any>((from, to) => supabase.from('material_requests').select('*').order('created_at',{ascending:false}).range(from, to)),
      // Quotes scale with (and can exceed) material_requests count — several
      // quotes are gathered per request — so cap risk tracks the same import.
      fetchAllPages<any>((from, to) => supabase.from('supplier_quotes').select('*').order('quoted_price').range(from, to)),
      fetchAllPages<any>((from, to) => supabase.from('purchase_orders').select('*, purchase_order_items(*)').order('created_at',{ascending:false}).range(from, to)),
      supabase.from('material_replenishments').select('*').not('purchase_order_id','is',null),
      supabase.from('purchase_order_invoices').select('*'),
      supabase.from('inventory').select('id,name,unit'),
      // Quotations that now carry a client PO — lets pre-sale material requests count as 'active PO'
      fetchAllPages<any>((from, to) => supabase.from('quotations').select('id,po_number').not('po_number','is',null).range(from, to)),
    ])
    setQuotePoMap(Object.fromEntries((quoPos||[]).filter((q:any)=>(q.po_number||'').trim()).map((q:any)=>[q.id,q.po_number])))
    setSuppliers(sup||[]); setSupplierMaterials(supMat||[]); setRequests(reqs||[]); setQuotes(qts||[])
    setOrders(ords||[]); setReceipts(recs||[]); setInvoices(invs||[]); setInventoryItems(inv||[])
    setLoading(false)
  },[supabase])
  useEffect(()=>{ fetchAll() },[fetchAll])
  useEffect(()=>{ setReqPage(1) },[tab])
  useEffect(()=>{ setOrderPage(1) },[tab])
  useEffect(()=>{ window.scrollTo({top:0, behavior:'smooth'}) },[reqPage, orderPage])

  // Most-recent-first by created_at — a bulk historical import lands many
  // rows within the same minute, but neither table carries a more
  // business-meaningful date field (no request/order date column is used
  // anywhere in this page), so created_at is the best available signal.
  const byRecency = (a:any,b:any) => (b.created_at||'').localeCompare(a.created_at||'')

  // ══════════════════════════════════════════════════════════════════════════
  // SUPPLIERS
  // ══════════════════════════════════════════════════════════════════════════
  const [showSupModal,setShowSupModal]=useState(false)
  const [selectedSup,setSelectedSup]=useState<any>(null)
  const [supForm,setSupForm]=useState({name:'',contact_person:'',phone:'',email:'',address:''})
  const openNewSupplier = () => { setSupForm({name:'',contact_person:'',phone:'',email:'',address:''}); setSelectedSup(null); setShowSupModal(true) }
  const openEditSupplier = (s:any) => { setSupForm({name:s.name,contact_person:s.contact_person||'',phone:s.phone||'',email:s.email||'',address:s.address||''}); setSelectedSup(s); setShowSupModal(true) }
  const saveSupplier = async () => {
    if (!supForm.name.trim()) return setError('Supplier name is required.')
    setSaving(true); setError('')
    const payload = { ...supForm }
    const { error } = selectedSup
      ? await supabase.from('suppliers').update(payload).eq('id', selectedSup.id)
      : await supabase.from('suppliers').insert(payload)
    if (error) setError(error.message)
    else { await fetchAll(); setShowSupModal(false) }
    setSaving(false)
  }
  const deleteSupplier = async (s:any) => {
    if (!window.confirm(`Delete ${s.name}? This also removes their material price list.`)) return
    await supabase.from('supplier_materials').delete().eq('supplier_id', s.id)
    await supabase.from('suppliers').delete().eq('id', s.id)
    await fetchAll()
  }

  const [expandedSupId,setExpandedSupId]=useState<string|null>(null)
  const [newMatForm,setNewMatForm]=useState({material_name:'',unit:'',price:'',inventory_id:''})
  const addSupplierMaterial = async (supplierId:string) => {
    if (!newMatForm.material_name.trim()) return
    await supabase.from('supplier_materials').insert({
      supplier_id: supplierId, material_name: newMatForm.material_name.trim(),
      unit: newMatForm.unit, price: Number(newMatForm.price)||0, inventory_id: newMatForm.inventory_id||null,
    })
    setNewMatForm({material_name:'',unit:'',price:'',inventory_id:''})
    await fetchAll()
  }
  const deleteSupplierMaterial = async (id:string) => {
    await supabase.from('supplier_materials').delete().eq('id', id)
    await fetchAll()
  }

  // ══════════════════════════════════════════════════════════════════════════
  // MATERIAL REQUESTS + QUOTE COMPARISON
  // ══════════════════════════════════════════════════════════════════════════
  const [expandedReqId,setExpandedReqId]=useState<string|null>(null)
  const [showNewReqModal,setShowNewReqModal]=useState(false)
  const [reqForm,setReqForm]=useState({po_number:'',project_reference:'',material_name:'',dimension:'',qty_needed:'',unit:'',requested_by:'',notes:''})
  const openNewRequest = () => { setReqForm({po_number:'',project_reference:'',material_name:'',dimension:'',qty_needed:'',unit:'',requested_by:'',notes:''}); setShowNewReqModal(true) }
  const saveNewRequest = async () => {
    if (!reqForm.material_name.trim()) return setError('Material name is required.')
    if (!reqForm.qty_needed || Number(reqForm.qty_needed)<=0) return setError('Enter a valid quantity.')
    setSaving(true); setError('')
    const { error } = await supabase.from('material_requests').insert({
      po_number: reqForm.po_number||null, project_reference: reqForm.project_reference||null,
      material_name: reqForm.material_name.trim(), dimension: reqForm.dimension||null,
      qty_needed: Number(reqForm.qty_needed), unit: reqForm.unit||null,
      requested_by: reqForm.requested_by||null, notes: reqForm.notes||null,
    })
    if (error) setError(error.message)
    else { await fetchAll(); setShowNewReqModal(false) }
    setSaving(false)
  }

  const [quoteForm,setQuoteForm]=useState({supplier_id:'',quoted_price:'',notes:''})
  const addQuote = async (requestId:string) => {
    if (!quoteForm.supplier_id) return setError('Select a supplier.')
    if (!quoteForm.quoted_price) return setError('Enter a quoted price.')
    setError('')
    await supabase.from('supplier_quotes').insert({
      material_request_id: requestId, supplier_id: quoteForm.supplier_id,
      quoted_price: Number(quoteForm.quoted_price), notes: quoteForm.notes||null,
    })
    await supabase.from('material_requests').update({status:'Comparing'}).eq('id', requestId).eq('status','Pending Quotes')

    // Register this into the supplier's persistent materials list if it
    // isn't already there — previously a quote only ever lived as a one-off
    // record tied to this specific request, so a supplier's price list on
    // file never grew from real quote history, only from manual entry.
    const req = requests.find((r:any)=>r.id===requestId)
    if (req) {
      const already = supplierMaterials.some((m:any) => m.supplier_id===quoteForm.supplier_id && m.material_name.toLowerCase().trim()===req.material_name.toLowerCase().trim())
      if (!already) {
        await supabase.from('supplier_materials').insert({
          supplier_id: quoteForm.supplier_id, material_name: req.material_name,
          unit: req.unit||null, price: Number(quoteForm.quoted_price), inventory_id: null,
        })
      }
    }

    setQuoteForm({supplier_id:'',quoted_price:'',notes:''})
    await fetchAll()
  }
  const deleteQuote = async (id:string) => { await supabase.from('supplier_quotes').delete().eq('id', id); await fetchAll() }

  const approveQuote = async (request:any, quote:any) => {
    if (!window.confirm(`Approve this quote from ${suppliers.find(s=>s.id===quote.supplier_id)?.name} at ${fmt(quote.quoted_price)}? This marks the request Approved and ready for PO release.`)) return
    await supabase.from('supplier_quotes').update({selected:false}).eq('material_request_id', request.id)
    await supabase.from('supplier_quotes').update({selected:true}).eq('id', quote.id)
    await supabase.from('material_requests').update({status:'Approved'}).eq('id', request.id)
    await fetchAll()
  }

  const cancelRequest = async (id:string) => {
    if (!window.confirm('Cancel this material request?')) return
    await supabase.from('material_requests').update({status:'Cancelled'}).eq('id', id)
    await fetchAll()
  }

  // ── Batch select + delete ────────────────────────────────────────────────
  const [selectedReqIds,setSelectedReqIds]=useState<Record<string,boolean>>({})
  const toggleReqSelected = (id:string) => setSelectedReqIds(p=>({...p,[id]:!p[id]}))
  const selectedReqCount = Object.values(selectedReqIds).filter(Boolean).length
  const clearReqSelection = () => setSelectedReqIds({})
  const deleteSelectedRequests = async () => {
    const ids = Object.entries(selectedReqIds).filter(([,v])=>v).map(([id])=>id)
    if (ids.length === 0) return
    if (!window.confirm(`Permanently delete ${ids.length} material request${ids.length===1?'':'s'}? This also removes any supplier quotes attached to them. This can't be undone.`)) return
    setSaving(true); setError('')
    // Clean up linked quotes first to avoid a foreign key violation on delete.
    await supabase.from('supplier_quotes').delete().in('material_request_id', ids)
    const { error } = await supabase.from('material_requests').delete().in('id', ids)
    if (error) setError(error.message)
    else { clearReqSelection(); await fetchAll() }
    setSaving(false)
  }

  // ══════════════════════════════════════════════════════════════════════════
  // PURCHASE ORDER RELEASE — one PO can now bundle several approved requests
  // headed to the same supplier into a single multi-line Purchase Order,
  // matching how a real supplier PO groups several materials together.
  // ══════════════════════════════════════════════════════════════════════════
  const releasePOBundle = async (bundleRequests:any[], supplierId:string) => {
    if (bundleRequests.length === 0) return setError('Select at least one item to include in this Purchase Order.')
    const lines = bundleRequests.map(req => {
      const winning = quotes.find(q=>q.material_request_id===req.id && q.selected)
      return { req, winning }
    })
    if (lines.some(l=>!l.winning)) return setError('One or more selected items has no approved quote.')
    const totalValue = lines.reduce((s,l)=>s+Number(l.req.qty_needed)*Number(l.winning.quoted_price),0)
    const needsApproval = totalValue >= approvalThreshold
    const supName = suppliers.find(s=>s.id===supplierId)?.name
    const itemsSummary = lines.map(l=>`• ${l.req.qty_needed} ${l.req.unit||''} of ${l.req.material_name}`).join('\n')
    if (!window.confirm(`Release a Purchase Order to ${supName} for ${lines.length} item${lines.length===1?'':'s'} (${fmt(totalValue)}):\n\n${itemsSummary}${needsApproval ? `\n\nThis is above the ${fmt(approvalThreshold)} approval threshold — it will need sign-off from a full-access user before it's actually released.` : ''}`)) return
    const expectedRaw = window.prompt('Expected delivery date (YYYY-MM-DD)? Leave blank to skip — this powers the supplier on-time tracking. Applies to all items in this PO.', '')
    const expected = expectedRaw && /^\d{4}-\d{2}-\d{2}$/.test(expectedRaw.trim()) ? expectedRaw.trim() : null
    const paymentTermsRaw = window.prompt('Payment terms for this PO?', 'Cash On Delivery')
    const paymentTerms = paymentTermsRaw?.trim() || 'Cash On Delivery'
    setSaving(true); setError('')
    const poId = `SPO-${new Date().getFullYear()}-${String(orders.length+1).padStart(3,'0')}`
    // Client PO reference on the header is informational — each line item
    // still carries its own material_request_id, which is the real link
    // back to whichever project/client PO actually needs it.
    const { error: hErr } = await supabase.from('purchase_orders').insert({
      id: poId, supplier_id: supplierId, po_number: lines[0].req.po_number || null,
      expected_delivery: expected, payment_terms: paymentTerms, status: needsApproval ? 'Pending Approval' : 'Released',
    })
    if (hErr) { setError(hErr.message); setSaving(false); return }
    const itemInserts = lines.map((l,i) => ({
      id: `POI-${poId}-${i+1}`, purchase_order_id: poId, material_request_id: l.req.id,
      material_name: l.req.material_name, dimension: l.req.dimension,
      qty: l.req.qty_needed, qty_received: 0, unit: l.req.unit, unit_price: l.winning.quoted_price,
    }))
    const { error: iErr } = await supabase.from('purchase_order_items').insert(itemInserts)
    if (iErr) { setError(iErr.message); setSaving(false); return }
    await Promise.all(lines.map(l => supabase.from('material_requests').update({status: needsApproval ? 'Approved' : 'PO Released'}).eq('id', l.req.id)))
    await fetchAll()
    setSaving(false)
  }

  const approvePO = async (order:any) => {
    if (!fullAccess) return
    const total = (order.purchase_order_items||[]).reduce((s:number,i:any)=>s+Number(i.qty)*Number(i.unit_price),0)
    if (!window.confirm(`Approve this ₱${total.toLocaleString('en-PH',{minimumFractionDigits:2})} Purchase Order? This releases it for receiving.`)) return
    await supabase.from('purchase_orders').update({ status:'Released', approved_by: currentUserName, approved_at: new Date().toISOString() }).eq('id', order.id)
    await Promise.all((order.purchase_order_items||[]).map((i:any) => i.material_request_id && supabase.from('material_requests').update({status:'PO Released'}).eq('id', i.material_request_id)))
    await fetchAll()
  }

  // ══════════════════════════════════════════════════════════════════════════
  // RECEIVING now happens exclusively in Inventory (Tool Keeper) — this
  // module only handles Invoicing (below) once Inventory reports goods as
  // received.
  // ══════════════════════════════════════════════════════════════════════════
  const [invoiceForm,setInvoiceForm]=useState<Record<string,{invoice_number:string,amount:string,payment_terms:string}>>({})
  const [bundleSelections,setBundleSelections]=useState<Record<string,boolean>>({})

  // Step 1: Record Invoice — purchasing-side bookkeeping only. Confirms the
  // supplier's invoice/reference has been received and captures payment
  // terms, but does NOT touch Accounting — that only happens once it's
  // actually paid (Step 2 below). This is deliberately a separate action so
  // "we have the invoice in hand" and "the account is closed" can't be
  // conflated.
  const recordInvoice = async (order:any) => {
    const f = invoiceForm[order.id]
    const totalValue = (order.purchase_order_items||[]).reduce((s:number,i:any)=>s+Number(i.qty)*Number(i.unit_price),0)
    const remainingToInvoice = totalValue - Number(order.amount_invoiced||0)
    const amount = Number(f?.amount) || remainingToInvoice
    if (amount > remainingToInvoice + 0.0001) return setError(`Only ${fmt(remainingToInvoice)} remains to be invoiced on this PO.`)
    setError('')
    await supabase.from('purchase_order_invoices').insert({
      purchase_order_id: order.id, invoice_number: f?.invoice_number||null, amount, payment_method: null, sales_invoice_number: null, expense_id: null,
    })
    const newAmountInvoiced = Number(order.amount_invoiced||0) + amount
    const fullyInvoiced = newAmountInvoiced >= totalValue - 0.0001
    await supabase.from('purchase_orders').update({
      amount_invoiced: newAmountInvoiced, status: fullyInvoiced ? 'Invoiced' : 'Partially Invoiced',
      payment_terms: f?.payment_terms || order.payment_terms || null,
    }).eq('id', order.id)
    setInvoiceForm(p=>({...p,[order.id]:{invoice_number:'',amount:'',payment_terms:''}}))
    await fetchAll()
  }

  // Step 2: Mark as Paid — the ONLY action that creates the Accounting
  // expense. Requires the supplier's actual Sales Invoice Number, since
  // that's what Accounting needs to close the account against — the
  // purchasing-side reference # from Step 1 isn't sufficient on its own.
  const [payForm,setPayForm]=useState<Record<string,{sales_invoice_number:string,amount:string,payment_method:string}>>({})
  const markPOPaid = async (order:any) => {
    const f = payForm[order.id]
    if (!f?.sales_invoice_number?.trim()) return setError("The supplier's Sales Invoice Number is required to mark this as paid.")
    const remainingToPay = Number(order.amount_invoiced||0) - Number(order.amount_paid||0)
    const amount = Number(f?.amount) || remainingToPay
    if (amount > remainingToPay + 0.0001) return setError(`Only ${fmt(remainingToPay)} remains to be paid on this PO.`)
    setError('')
    const expenseId = `EXP-${Date.now()}`
    const { error: e1 } = await supabase.from('expenses').insert({
      id: expenseId, date: new Date().toISOString().slice(0,10), category: 'Materials/BOM',
      description: `${suppliers.find(s=>s.id===order.supplier_id)?.name||'Supplier'} — PO ${order.id} (Sales Inv# ${f.sales_invoice_number.trim()})`,
      amount, payment_method: f?.payment_method||'Cash', status:'Paid',
    })
    if (e1) return setError(e1.message)
    await supabase.from('purchase_order_invoices').insert({
      purchase_order_id: order.id, invoice_number: null, sales_invoice_number: f.sales_invoice_number.trim(),
      amount, payment_method: f?.payment_method||'Cash', expense_id: expenseId,
    })
    const newAmountPaid = Number(order.amount_paid||0) + amount
    const fullyPaid = newAmountPaid >= Number(order.amount_invoiced||0) - 0.0001
    await supabase.from('purchase_orders').update({
      amount_paid: newAmountPaid, status: fullyPaid ? 'Paid' : 'Partially Paid',
    }).eq('id', order.id)

    // Offer to log this payment straight into the Bank Ledger (Accounting)
    // instead of retyping it there, if there's an open statement period.
    const { data: acct } = await supabase.from('bank_accounts').select('id').limit(1).maybeSingle()
    if (acct) {
      const { data: openStmt } = await supabase.from('bank_statements').select('id,period_label').eq('bank_account_id', acct.id).eq('status', 'Open').order('start_date',{ascending:false}).limit(1).maybeSingle()
      if (openStmt && window.confirm(`Also log this ${fmt(amount)} supplier payment as a Bank Withdrawal in "${openStmt.period_label}"?`)) {
        await supabase.from('bank_transactions').insert({
          id: `TXN-${Date.now()}`, bank_statement_id: openStmt.id, bank_account_id: acct.id,
          date: new Date().toISOString().slice(0,10),
          particulars: `${suppliers.find(s=>s.id===order.supplier_id)?.name||'Supplier'} — PO ${order.id} (Sales Inv# ${f.sales_invoice_number.trim()})`,
          amount, direction: 'Withdrawal', category: 'Supplier Payment', expense_id: expenseId,
        })
      }
    }

    setPayForm(p=>({...p,[order.id]:{sales_invoice_number:'',amount:'',payment_method:'Cash'}}))
    await fetchAll()
  }

  const statusColor = (s:string) => ({'Pending Quotes':C.gray,'Comparing':C.blue,'Approved':C.accent,'PO Released':C.purple,'Fulfilled':C.accent,'Cancelled':C.red,'Released':C.blue,'Delivered':C.amber,'Invoiced':C.amber,'Paid':C.accent,'Partially Paid':C.amber,'Pending Approval':C.amber,'Partially Delivered':C.amber,'Partially Invoiced':C.amber}[s]||C.gray)

  // ── Pagination (50/page, most-recent-first, applied on top of the
  // existing filters) ─────────────────────────────────────────────────────
  // ── Ready to Buy: quote approved + the work has a live client PO, but no supplier PO issued yet ──
  const orderedReqIds = new Set(orders.flatMap((o:any)=>(o.purchase_order_items||[]).map((i:any)=>i.material_request_id)))
  const effectivePo = (r:any) => (r.po_number || (r.quotation_id ? quotePoMap[r.quotation_id] : '') || '').trim()
  const readyToBuy = requests.filter(r=>r.status==='Approved' && !r.archived && effectivePo(r) && !orderedReqIds.has(r.id) && quotes.some(q=>q.material_request_id===r.id && q.selected))
  const readyGroups = (() => {
    const byPo: Record<string, Record<string, {supplierId:string, reqs:any[], total:number}>> = {}
    readyToBuy.forEach(r=>{
      const win = quotes.find(q=>q.material_request_id===r.id && q.selected)
      const po = effectivePo(r)
      byPo[po] = byPo[po] || {}
      const g = byPo[po][win.supplier_id] = byPo[po][win.supplier_id] || {supplierId:win.supplier_id, reqs:[], total:0}
      g.reqs.push(r); g.total += Number(r.qty_needed)*Number(win.quoted_price)
    })
    return Object.entries(byPo).sort(([a],[b])=>a.localeCompare(b))
  })()
  const filteredRequests = requests.filter(r=>r.status!=='Cancelled' && !r.archived).slice().sort(byRecency)
  const reqPageCount = Math.max(1, Math.ceil(filteredRequests.length / PAGE_SIZE))
  const currentReqPage = Math.min(reqPage, reqPageCount)
  const pagedRequests = filteredRequests.slice((currentReqPage-1)*PAGE_SIZE, currentReqPage*PAGE_SIZE)

  const sortedOrders = orders.slice().sort(byRecency)
  const orderPageCount = Math.max(1, Math.ceil(sortedOrders.length / PAGE_SIZE))
  const currentOrderPage = Math.min(orderPage, orderPageCount)
  const pagedOrders = sortedOrders.slice((currentOrderPage-1)*PAGE_SIZE, currentOrderPage*PAGE_SIZE)

  return (
    <div>
      {/* Tabs */}
      <div style={{display:'flex',gap:8,marginBottom:18,flexWrap:'wrap'}}>
        {(['requests','suppliers','orders'] as const).map(t=>(
          <button key={t} onClick={()=>setTab(t)} style={{padding:'8px 18px',borderRadius:6,border:`1.5px solid ${tab===t?C.accent:C.lightGray}`,background:tab===t?C.accent:C.white,color:tab===t?C.white:C.gray,fontSize:11,fontWeight:800,cursor:'pointer',fontFamily:'inherit',letterSpacing:1,textTransform:'uppercase'}}>
            {({requests:'Material Requests',suppliers:'Suppliers',orders:'Purchase Orders'})[t]}
          </button>
        ))}
      </div>

      {error && <div style={{background:`${C.red}12`,border:`1px solid ${C.red}44`,borderRadius:8,padding:'10px 16px',fontSize:12,color:C.red,marginBottom:16}}>{error} <button onClick={()=>setError('')} style={{float:'right',background:'none',border:'none',color:C.red,cursor:'pointer',fontWeight:800}}>✕</button></div>}

      {loading ? (
        <div style={{background:C.white,borderRadius:12,padding:60,textAlign:'center',boxShadow:'0 2px 16px rgba(0,0,0,0.07)'}}>
          <div style={{fontSize:32,marginBottom:12}}>⏳</div>
          <div style={{fontSize:13,color:C.gray,fontWeight:700}}>Loading purchasing data…</div>
        </div>
      ) : (
      <>

      {/* ══════════════════ MATERIAL REQUESTS ══════════════════ */}
      {tab==='requests' && (
        <div>
          <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:16}}>
            <div style={{fontSize:11,color:C.gray}}>Requests arrive here from Projects' BOM fulfillment, or can be logged manually for non-PO work.</div>
            {canEdit && <button onClick={openNewRequest} style={{padding:'9px 18px',background:`linear-gradient(135deg,${C.accent},${C.midGreen})`,border:'none',borderRadius:6,color:C.white,fontSize:11,fontWeight:800,letterSpacing:1,cursor:'pointer'}}>+ Log Material Request</button>}
          </div>

          {canEdit && selectedReqCount>0 && (
            <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',background:`${C.red}0a`,border:`1px solid ${C.red}44`,borderRadius:8,padding:'10px 16px',marginBottom:12}}>
              <span style={{fontSize:12,fontWeight:700,color:C.dark}}>{selectedReqCount} selected</span>
              <div style={{display:'flex',gap:8}}>
                <button onClick={clearReqSelection} style={{padding:'7px 14px',fontSize:11,fontWeight:700,background:'transparent',border:`1px solid ${C.lightGray}`,color:C.gray,borderRadius:6,cursor:'pointer'}}>Clear</button>
                <button onClick={deleteSelectedRequests} disabled={saving} style={{padding:'7px 14px',fontSize:11,fontWeight:700,background:C.red,border:'none',color:C.white,borderRadius:6,cursor:'pointer'}}>{saving?'Deleting…':`🗑 Delete ${selectedReqCount}`}</button>
              </div>
            </div>
          )}

          {readyGroups.length>0 && (
            <div style={{background:`${C.accent}0d`,border:`1.5px solid ${C.accent}66`,borderRadius:12,padding:'14px 18px',marginBottom:16}}>
              <div style={{fontSize:12,fontWeight:900,color:C.darkGreen,letterSpacing:1,textTransform:'uppercase',marginBottom:4}}>🛒 Ready to Buy — approved quotes with an active PO ({readyToBuy.length})</div>
              <div style={{fontSize:11,color:C.gray,marginBottom:10}}>Quotes are approved and the client PO is in — these just need a supplier Purchase Order.</div>
              {readyGroups.map(([po, bySup])=>(
                <div key={po} style={{background:C.white,border:`1px solid ${C.lightGray}`,borderRadius:8,padding:'10px 14px',marginBottom:8}}>
                  <div style={{fontSize:11,fontWeight:900,color:C.dark,marginBottom:6}}>Project / PO {po}</div>
                  {Object.values(bySup).map(g=>(
                    <div key={g.supplierId} style={{display:'flex',justifyContent:'space-between',alignItems:'flex-start',gap:12,padding:'6px 0',borderTop:`1px dashed ${C.lightGray}`}}>
                      <div style={{fontSize:11,color:C.dark}}>
                        <b>{suppliers.find(s=>s.id===g.supplierId)?.name||'Supplier'}</b> · {fmt(g.total)}
                        <div style={{color:C.gray,marginTop:2}}>{g.reqs.map(r=>`${r.qty_needed} ${r.unit||''} ${r.material_name}`).join(' · ')}</div>
                      </div>
                      {canEdit && <button disabled={saving} onClick={()=>releasePOBundle(g.reqs,g.supplierId)} style={{padding:'7px 14px',fontSize:10,fontWeight:800,background:C.accent,border:'none',color:C.white,borderRadius:6,cursor:'pointer',whiteSpace:'nowrap'}}>Release PO →</button>}
                    </div>
                  ))}
                </div>
              ))}
            </div>
          )}

          {filteredRequests.length===0
            ? <div style={{background:C.white,borderRadius:12,padding:40,textAlign:'center',color:C.gray,boxShadow:'0 2px 16px rgba(0,0,0,0.07)'}}>No material requests yet.</div>
            : <>
          <div style={{fontSize:11,color:C.gray,fontWeight:700,marginBottom:10}}>
            {`Showing ${(currentReqPage-1)*PAGE_SIZE+1}–${Math.min(currentReqPage*PAGE_SIZE, filteredRequests.length)} of ${filteredRequests.length}`}
          </div>
          {pagedRequests.map(req=>{
              const reqQuotes = quotes.filter(q=>q.material_request_id===req.id).sort((a,b)=>a.quoted_price-b.quoted_price)
              const isExpanded = expandedReqId===req.id
              const winningQuote = reqQuotes.find(q=>q.selected)
              const hasReleasedPO = orders.some(o=>(o.purchase_order_items||[]).some((i:any)=>i.material_request_id===req.id))
              return (
                <div key={req.id} style={{background:C.white,borderRadius:12,marginBottom:12,boxShadow:'0 2px 16px rgba(0,0,0,0.07)',overflow:'hidden'}}>
                  <div onClick={()=>setExpandedReqId(isExpanded?null:req.id)} style={{padding:'14px 20px',cursor:'pointer',display:'flex',justifyContent:'space-between',alignItems:'center',flexWrap:'wrap',gap:10}}>
                    <div style={{display:'flex',alignItems:'center',gap:12}}>
                      {canEdit && !hasReleasedPO && (
                        <input type="checkbox" checked={!!selectedReqIds[req.id]} onClick={e=>e.stopPropagation()} onChange={()=>toggleReqSelected(req.id)} style={{width:16,height:16,cursor:'pointer',flexShrink:0}}/>
                      )}
                      <div>
                        <div style={{fontWeight:800,fontSize:13,color:C.dark,display:'flex',alignItems:'center',gap:8}}>
                          {req.material_name} {req.dimension && <span style={{color:C.gray,fontWeight:600}}>({req.dimension})</span>}
                          {req.quotation_id && <span style={{fontSize:9,fontWeight:800,color:C.blue,background:`${C.blue}15`,padding:'2px 8px',borderRadius:10}}>PRE-SALE</span>}
                        </div>
                        <div style={{fontSize:11,color:C.gray,marginTop:2}}>{req.qty_needed} {req.unit} {req.quotation_id ? `— Quotation ${req.quotation_id}` : req.po_number ? `— PO ${req.po_number}` : req.project_reference ? `— ${req.project_reference}` : ''} {req.requested_by && `· requested by ${req.requested_by}`}</div>
                      </div>
                    </div>
                    <div style={{display:'flex',alignItems:'center',gap:10}}>
                      <span style={{padding:'3px 12px',borderRadius:20,background:`${statusColor(req.status)}18`,color:statusColor(req.status),fontSize:10,fontWeight:800}}>{req.status}</span>
                      <span style={{color:C.gray,fontSize:14}}>{isExpanded?'▲':'▼'}</span>
                    </div>
                  </div>
                  {isExpanded && (
                    <div style={{padding:'0 20px 18px',borderTop:`1px solid ${C.lightGray}`}}>
                      {req.quotation_id && (() => {
                        const priorRequestIds = requests.filter(r => r.quotation_id === req.quotation_id && r.id !== req.id).map(r => r.id)
                        const priorQuotes = quotes.filter(q => priorRequestIds.includes(q.material_request_id))
                        if (priorQuotes.length === 0) return null
                        return (
                          <div style={{background:`${C.blue}0a`,border:`1px solid ${C.blue}33`,borderRadius:8,padding:'10px 14px',margin:'14px 0'}}>
                            <div style={{fontSize:10,fontWeight:800,color:C.blue,textTransform:'uppercase',marginBottom:6}}>Previous Quotes for Quotation {req.quotation_id}</div>
                            {priorQuotes.sort((a,b)=>a.quoted_price-b.quoted_price).map(q => (
                              <div key={q.id} style={{fontSize:11,color:C.dark,padding:'2px 0'}}>
                                {suppliers.find(s=>s.id===q.supplier_id)?.name || '—'} — <b style={{color:C.accent}}>{fmt(q.quoted_price)}</b> <span style={{color:C.gray}}>({q.quoted_date})</span>
                              </div>
                            ))}
                          </div>
                        )
                      })()}
                      <div style={{fontSize:10,fontWeight:800,color:C.gray,textTransform:'uppercase',margin:'14px 0 8px'}}>Supplier Quotes</div>
                      {reqQuotes.length===0
                        ? <div style={{fontSize:11,color:C.gray,fontStyle:'italic',marginBottom:10}}>No quotes gathered yet.</div>
                        : (
                          <table style={{width:'100%',borderCollapse:'collapse',fontSize:12,marginBottom:12}}>
                            <thead><tr style={{background:'#f4f7f5'}}>
                              {['Supplier','Price','Date','Notes',''].map(h=><th key={h} style={{padding:'6px 10px',textAlign:'left',fontSize:9,fontWeight:800,color:C.gray,textTransform:'uppercase'}}>{h}</th>)}
                            </tr></thead>
                            <tbody>{reqQuotes.map(q=>(
                              <tr key={q.id} style={{borderBottom:`1px solid ${C.lightGray}`,background:q.selected?`${C.accent}0a`:'transparent'}}>
                                <td style={{padding:'6px 10px',fontWeight:700}}>{suppliers.find(s=>s.id===q.supplier_id)?.name||'—'} {q.selected && <span style={{color:C.accent,fontSize:10}}>✓ Selected</span>}</td>
                                <td style={{padding:'6px 10px',fontWeight:800,color:reqQuotes[0].id===q.id?C.accent:C.dark}}>{fmt(q.quoted_price)}{reqQuotes[0].id===q.id && <span style={{fontSize:9,color:C.accent,marginLeft:4}}>lowest</span>}</td>
                                <td style={{padding:'6px 10px',color:C.gray}}>{q.quoted_date}</td>
                                <td style={{padding:'6px 10px',color:C.gray,fontSize:11}}>{q.notes||'—'}</td>
                                <td style={{padding:'6px 10px',display:'flex',gap:6}}>
                                  {canEdit && !winningQuote && req.status!=='Cancelled' && <button onClick={()=>approveQuote(req,q)} style={{background:`${C.accent}18`,border:`1px solid ${C.accent}44`,color:C.accent,borderRadius:4,padding:'4px 9px',cursor:'pointer',fontSize:9,fontWeight:700}}>Approve</button>}
                                  {canEdit && !q.selected && <button onClick={()=>deleteQuote(q.id)} style={{background:`${C.red}18`,border:`1px solid ${C.red}44`,color:C.red,borderRadius:4,padding:'4px 9px',cursor:'pointer',fontSize:9,fontWeight:700}}>✕</button>}
                                </td>
                              </tr>
                            ))}</tbody>
                          </table>
                        )}

                      {canEdit && !winningQuote && (
                        <div style={{display:'grid',gridTemplateColumns:'1.5fr 1fr 1.5fr auto',gap:8,alignItems:'end',background:'#f9fbf9',padding:12,borderRadius:8,marginBottom:12}}>
                          <div>
                            <label style={{fontSize:9,color:C.gray,fontWeight:700}}>Supplier</label>
                            <select value={quoteForm.supplier_id} onChange={e=>setQuoteForm(p=>({...p,supplier_id:e.target.value}))} style={{...inputStyle,padding:'7px 9px'}}>
                              <option value="">Select…</option>
                              {suppliers.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}
                            </select>
                          </div>
                          <div>
                            <label style={{fontSize:9,color:C.gray,fontWeight:700}}>Quoted Price</label>
                            <input type="number" value={quoteForm.quoted_price} onChange={e=>setQuoteForm(p=>({...p,quoted_price:e.target.value}))} onFocus={e=>e.target.select()} onBlur={e=>{if(!e.target.value.trim())setQuoteForm(p=>({...p,quoted_price:'0'}))}} style={{...inputStyle,padding:'7px 9px'}}/>
                          </div>
                          <div>
                            <label style={{fontSize:9,color:C.gray,fontWeight:700}}>Notes</label>
                            <input value={quoteForm.notes} onChange={e=>setQuoteForm(p=>({...p,notes:e.target.value}))} onFocus={e=>e.target.select()} onBlur={e=>{if(!e.target.value.trim())setQuoteForm(p=>({...p,notes:'N/A'}))}} style={{...inputStyle,padding:'7px 9px'}}/>
                          </div>
                          <button onClick={()=>addQuote(req.id)} style={{padding:'8px 16px',background:C.blue,border:'none',borderRadius:6,color:C.white,fontSize:11,fontWeight:700,cursor:'pointer'}}>+ Add Quote</button>
                        </div>
                      )}

                      <div style={{display:'flex',gap:8}}>
                        {canEdit && winningQuote && !hasReleasedPO && (
                          <button onClick={()=>releasePOBundle([req], winningQuote.supplier_id)} disabled={saving} style={{padding:'9px 18px',background:`linear-gradient(135deg,${C.purple},#6d28d9)`,border:'none',borderRadius:6,color:C.white,fontSize:11,fontWeight:800,cursor:'pointer'}}>🛒 Release Purchase Order</button>
                        )}
                        {canEdit && !hasReleasedPO && <button onClick={()=>cancelRequest(req.id)} style={{padding:'9px 18px',background:'transparent',border:`1px solid ${C.red}`,borderRadius:6,color:C.red,fontSize:11,fontWeight:700,cursor:'pointer'}}>Cancel Request</button>}
                      </div>
                    </div>
                  )}
                </div>
              )
            })}
          {reqPageCount > 1 && (
            <div style={{display:'flex',justifyContent:'center',alignItems:'center',gap:10,marginTop:16}}>
              <button onClick={()=>setReqPage(p=>Math.max(1,p-1))} disabled={currentReqPage===1} style={{padding:'7px 14px',borderRadius:6,border:`1.5px solid ${C.lightGray}`,background:C.white,color:currentReqPage===1?C.lightGray:C.dark,fontSize:11,fontWeight:700,cursor:currentReqPage===1?'default':'pointer'}}>← Prev</button>
              <span style={{fontSize:11,fontWeight:700,color:C.gray}}>Page {currentReqPage} of {reqPageCount}</span>
              <button onClick={()=>setReqPage(p=>Math.min(reqPageCount,p+1))} disabled={currentReqPage===reqPageCount} style={{padding:'7px 14px',borderRadius:6,border:`1.5px solid ${C.lightGray}`,background:C.white,color:currentReqPage===reqPageCount?C.lightGray:C.dark,fontSize:11,fontWeight:700,cursor:currentReqPage===reqPageCount?'default':'pointer'}}>Next →</button>
            </div>
          )}
          </>}
        </div>
      )}

      {/* ══════════════════ SUPPLIERS ══════════════════ */}
      {tab==='suppliers' && (
        <div>
          {canEdit && <button onClick={openNewSupplier} style={{padding:'9px 18px',background:`linear-gradient(135deg,${C.accent},${C.midGreen})`,border:'none',borderRadius:6,color:C.white,fontSize:11,fontWeight:800,letterSpacing:1,cursor:'pointer',marginBottom:16}}>+ New Supplier</button>}
          {suppliers.length===0
            ? <div style={{background:C.white,borderRadius:12,padding:40,textAlign:'center',color:C.gray,boxShadow:'0 2px 16px rgba(0,0,0,0.07)'}}>No suppliers registered yet.</div>
            : suppliers.map(s=>{
              const isExpanded = expandedSupId===s.id
              const mats = supplierMaterials.filter(m=>m.supplier_id===s.id)
              // On-time rate: compare each delivered PO's expected_delivery
              // against the actual date its receipt was logged.
              const supOrders = orders.filter(o=>o.supplier_id===s.id && o.expected_delivery)
              const withReceipt = supOrders.map(o=>({o, receipt: receipts.find(r=>r.purchase_order_id===o.id)})).filter(x=>x.receipt)
              const onTimeCount = withReceipt.filter(x=>x.receipt.date <= x.o.expected_delivery).length
              const onTimePct = withReceipt.length>0 ? Math.round(onTimeCount/withReceipt.length*100) : null
              return (
                <div key={s.id} style={{background:C.white,borderRadius:12,marginBottom:12,boxShadow:'0 2px 16px rgba(0,0,0,0.07)',overflow:'hidden'}}>
                  <div style={{padding:'14px 20px',display:'flex',justifyContent:'space-between',alignItems:'center',flexWrap:'wrap',gap:10}}>
                    <div onClick={()=>setExpandedSupId(isExpanded?null:s.id)} style={{cursor:'pointer',flex:1}}>
                      <div style={{fontWeight:800,fontSize:13,color:C.dark}}>{s.name}</div>
                      <div style={{fontSize:11,color:C.gray,marginTop:2}}>{s.contact_person||'—'} {s.phone && `· ${s.phone}`} · {mats.length} material{mats.length===1?'':'s'} on file</div>
                    </div>
                    {onTimePct!==null && (
                      <span title={`${onTimeCount} of ${withReceipt.length} tracked deliveries on time`} style={{fontSize:10,fontWeight:800,color:onTimePct>=80?C.accent:onTimePct>=50?C.amber:C.red,background:`${onTimePct>=80?C.accent:onTimePct>=50?C.amber:C.red}18`,padding:'4px 10px',borderRadius:20}}>
                        {onTimePct}% on-time
                      </span>
                    )}
                    {canEdit && (
                      <div style={{display:'flex',gap:6}}>
                        <button onClick={()=>openEditSupplier(s)} style={{background:`${C.blue}18`,border:`1px solid ${C.blue}44`,color:C.blue,borderRadius:5,padding:'5px 12px',cursor:'pointer',fontSize:10,fontWeight:700}}>Edit</button>
                        <button onClick={()=>deleteSupplier(s)} style={{background:`${C.red}18`,border:`1px solid ${C.red}44`,color:C.red,borderRadius:5,padding:'5px 12px',cursor:'pointer',fontSize:10,fontWeight:700}}>Delete</button>
                      </div>
                    )}
                  </div>
                  {isExpanded && (
                    <div style={{padding:'0 20px 18px',borderTop:`1px solid ${C.lightGray}`}}>
                      <div style={{fontSize:10,fontWeight:800,color:C.gray,textTransform:'uppercase',margin:'14px 0 8px'}}>Material Price List</div>
                      {mats.length>0 && (
                        <table style={{width:'100%',borderCollapse:'collapse',fontSize:12,marginBottom:10}}>
                          <thead><tr style={{background:'#f4f7f5'}}>{['Material','Unit','Price',''].map(h=><th key={h} style={{padding:'6px 10px',textAlign:'left',fontSize:9,fontWeight:800,color:C.gray,textTransform:'uppercase'}}>{h}</th>)}</tr></thead>
                          <tbody>{mats.map(m=>(
                            <tr key={m.id} style={{borderBottom:`1px solid ${C.lightGray}`}}>
                              <td style={{padding:'6px 10px',fontWeight:700}}>{m.material_name}</td>
                              <td style={{padding:'6px 10px',color:C.gray}}>{m.unit||'—'}</td>
                              <td style={{padding:'6px 10px',fontWeight:800,color:C.accent}}>{fmt(m.price)}</td>
                              <td style={{padding:'6px 10px'}}>{canEdit && <button onClick={()=>deleteSupplierMaterial(m.id)} style={{background:`${C.red}18`,border:`1px solid ${C.red}44`,color:C.red,borderRadius:4,padding:'3px 8px',cursor:'pointer',fontSize:9}}>✕</button>}</td>
                            </tr>
                          ))}</tbody>
                        </table>
                      )}
                      {canEdit && (
                        <div style={{display:'grid',gridTemplateColumns:'2fr 1fr 1fr auto',gap:8,alignItems:'end'}}>
                          <div><label style={{fontSize:9,color:C.gray,fontWeight:700}}>Material Name</label><input value={newMatForm.material_name} onChange={e=>setNewMatForm(p=>({...p,material_name:e.target.value.toUpperCase()}))} onFocus={e=>e.target.select()} style={{...inputStyle,padding:'7px 9px'}}/></div>
                          <div><label style={{fontSize:9,color:C.gray,fontWeight:700}}>Unit</label><select value={newMatForm.unit} onChange={e=>setNewMatForm(p=>({...p,unit:e.target.value}))} style={{...inputStyle,padding:'7px 9px'}}><option value="">Select…</option>{UNIT_OPTIONS.map(u=><option key={u} value={u}>{u}</option>)}</select></div>
                          <div><label style={{fontSize:9,color:C.gray,fontWeight:700}}>Price</label><input type="number" value={newMatForm.price} onChange={e=>setNewMatForm(p=>({...p,price:e.target.value}))} onFocus={e=>e.target.select()} onBlur={e=>{if(!e.target.value.trim())setNewMatForm(p=>({...p,price:'0'}))}} style={{...inputStyle,padding:'7px 9px'}}/></div>
                          <button onClick={()=>addSupplierMaterial(s.id)} style={{padding:'8px 16px',background:C.accent,border:'none',borderRadius:6,color:C.white,fontSize:11,fontWeight:700,cursor:'pointer'}}>+ Add</button>
                        </div>
                      )}
                    </div>
                  )}
                </div>
              )
            })}
        </div>
      )}

      {/* ══════════════════ PURCHASE ORDERS (Receiving + Invoicing) ══════════════════ */}
      {tab==='orders' && (
        <div>
          {(() => {
            const readyToIssue = requests.filter(r => r.status === 'Approved' && !orders.some(o => (o.purchase_order_items||[]).some((i:any)=>i.material_request_id===r.id)))
            if (readyToIssue.length === 0) return null
            const bySupplier: Record<string, any[]> = {}
            readyToIssue.forEach(req => {
              const winning = quotes.find(q => q.material_request_id === req.id && q.selected)
              const supId = winning?.supplier_id || '__none__'
              if (!bySupplier[supId]) bySupplier[supId] = []
              bySupplier[supId].push(req)
            })
            return (
              <div style={{ marginBottom: 20 }}>
                <div style={{ fontSize: 10, fontWeight: 800, color: C.purple, textTransform: 'uppercase', letterSpacing: 1, marginBottom: 10 }}>⚠ Ready to Issue — {readyToIssue.length} approved request{readyToIssue.length===1?'':'s'} awaiting a Purchase Order</div>
                {Object.entries(bySupplier).map(([supId, groupReqs]) => {
                  const sup = suppliers.find(s => s.id === supId)
                  const checkedReqs = groupReqs.filter(r => bundleSelections[r.id] !== false) // default checked
                  const groupTotal = checkedReqs.reduce((s,r) => {
                    const w = quotes.find(q=>q.material_request_id===r.id && q.selected)
                    return s + Number(r.qty_needed) * Number(w?.quoted_price||0)
                  }, 0)
                  return (
                    <div key={supId} style={{ background: `${C.purple}0a`, border: `1px solid ${C.purple}44`, borderRadius: 10, padding: '14px 18px', marginBottom: 10 }}>
                      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 10 }}>
                        <div style={{ fontWeight: 800, fontSize: 13, color: C.dark }}>{sup?.name || 'No supplier selected'} <span style={{ fontWeight: 600, color: C.gray, fontSize: 11 }}>— {groupReqs.length} item{groupReqs.length===1?'':'s'} ready</span></div>
                        {canEdit && supId!=='__none__' && <button onClick={() => releasePOBundle(checkedReqs, supId)} disabled={saving || checkedReqs.length===0} style={{ padding: '9px 18px', background: `linear-gradient(135deg,${C.purple},#6d28d9)`, border: 'none', borderRadius: 6, color: C.white, fontSize: 11, fontWeight: 800, cursor: 'pointer', whiteSpace: 'nowrap', opacity: checkedReqs.length===0?0.5:1 }}>🛒 Issue PO — {checkedReqs.length} item{checkedReqs.length===1?'':'s'} ({fmt(groupTotal)})</button>}
                      </div>
                      {groupReqs.map(req => {
                        const winning = quotes.find(q => q.material_request_id === req.id && q.selected)
                        const checked = bundleSelections[req.id] !== false
                        return (
                          <label key={req.id} style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '6px 0', cursor: 'pointer' }}>
                            <input type="checkbox" checked={checked} onChange={e=>setBundleSelections(p=>({...p,[req.id]:e.target.checked}))} style={{width:16,height:16,cursor:'pointer'}}/>
                            <div>
                              <div style={{ fontWeight: 700, fontSize: 12, color: C.dark }}>{req.material_name} {req.dimension && <span style={{ color: C.gray, fontWeight: 600 }}>({req.dimension})</span>}</div>
                              <div style={{ fontSize: 11, color: C.gray }}>{req.qty_needed} {req.unit} at {winning ? fmt(winning.quoted_price) : '—'} {req.po_number && `· Client PO ${req.po_number}`}</div>
                            </div>
                          </label>
                        )
                      })}
                    </div>
                  )
                })}
              </div>
            )
          })()}
          {sortedOrders.length===0
            ? <div style={{background:C.white,borderRadius:12,padding:40,textAlign:'center',color:C.gray,boxShadow:'0 2px 16px rgba(0,0,0,0.07)'}}>No purchase orders released yet.</div>
            : <>
          <div style={{fontSize:11,color:C.gray,fontWeight:700,marginBottom:10}}>
            {`Showing ${(currentOrderPage-1)*PAGE_SIZE+1}–${Math.min(currentOrderPage*PAGE_SIZE, sortedOrders.length)} of ${sortedOrders.length}`}
          </div>
          {pagedOrders.map(o=>{
              const sup = suppliers.find(s=>s.id===o.supplier_id)
              const items = o.purchase_order_items||[]
              const total = items.reduce((s:number,i:any)=>s+Number(i.qty)*Number(i.unit_price),0)
              const totalQty = items.reduce((s:number,i:any)=>s+Number(i.qty),0)
              const totalReceived = items.reduce((s:number,i:any)=>s+Number(i.qty_received||0),0)
              return (
                <div key={o.id} style={{background:C.white,borderRadius:12,padding:'16px 20px',marginBottom:12,boxShadow:'0 2px 16px rgba(0,0,0,0.07)'}}>
                  <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',flexWrap:'wrap',gap:10,marginBottom:10}}>
                    <div>
                      <div style={{fontWeight:800,fontSize:13,color:C.darkGreen}}>{o.id} — {sup?.name}</div>
                      <div style={{fontSize:11,color:C.gray,marginTop:2}}>{items.length} item{items.length===1?'':'s'} · {fmt(total)} {o.po_number && `· Client PO ${o.po_number}`} {o.expected_delivery && `· Expected ${o.expected_delivery}`}</div>
                    </div>
                    <span style={{padding:'3px 12px',borderRadius:20,background:`${statusColor(o.status)}18`,color:statusColor(o.status),fontSize:10,fontWeight:800}}>{o.status}</span>
                  </div>

                  <table style={{width:'100%',borderCollapse:'collapse',fontSize:11,marginBottom:8}}>
                    <thead><tr style={{borderBottom:`1px solid ${C.lightGray}`}}>
                      {['Item','Qty','Unit Price','Line Total','Received'].map(h=><th key={h} style={{padding:'4px 8px',textAlign:'left',color:C.gray,fontWeight:700,fontSize:9,textTransform:'uppercase'}}>{h}</th>)}
                    </tr></thead>
                    <tbody>{items.map((i:any)=>(
                      <tr key={i.id} style={{borderBottom:`1px solid ${C.lightGray}`}}>
                        <td style={{padding:'5px 8px',fontWeight:600}}>{i.material_name}{i.dimension?` (${i.dimension})`:''}</td>
                        <td style={{padding:'5px 8px',color:C.gray}}>{i.qty} {i.unit}</td>
                        <td style={{padding:'5px 8px',color:C.gray}}>{fmt(i.unit_price)}</td>
                        <td style={{padding:'5px 8px',fontWeight:700}}>{fmt(Number(i.qty)*Number(i.unit_price))}</td>
                        <td style={{padding:'5px 8px',color:Number(i.qty_received||0)>=Number(i.qty)?C.accent:C.gray,fontWeight:Number(i.qty_received||0)>=Number(i.qty)?800:400}}>{Number(i.qty_received||0)} of {i.qty}</td>
                      </tr>
                    ))}</tbody>
                  </table>

                  {(o.status==='Partially Delivered'||o.status==='Delivered'||o.status==='Partially Invoiced'||o.status==='Invoiced') && (
                    <div style={{display:'flex',gap:16,marginBottom:8,fontSize:10,color:C.gray}}>
                      <span>Received: <b style={{color:C.dark}}>{totalReceived} of {totalQty} units (across all items)</b></span>
                      <span>Invoiced: <b style={{color:C.dark}}>{fmt(Number(o.amount_invoiced||0))} of {fmt(total)}</b></span>
                    </div>
                  )}
                  <div style={{marginBottom:8}}>
                    <button onClick={()=>printSupplierPO(o, sup, currentUserName)} style={{padding:'5px 12px',fontSize:10,fontWeight:700,background:`${C.blue}12`,border:`1px solid ${C.blue}44`,color:C.blue,borderRadius:5,cursor:'pointer'}}>🖨 Export PO</button>
                  </div>

                  {o.status==='Pending Approval' && (
                    <div style={{background:`${C.amber}0a`,border:`1px solid ${C.amber}44`,borderRadius:8,padding:12,marginBottom:8,display:'flex',justifyContent:'space-between',alignItems:'center',flexWrap:'wrap',gap:10}}>
                      <span style={{fontSize:11,color:C.amber}}>⚠ Above the {fmt(approvalThreshold)} threshold — needs sign-off from a full-access user before it can be received.</span>
                      {fullAccess ? (
                        <button onClick={()=>approvePO(o)} style={{padding:'7px 16px',background:C.amber,border:'none',borderRadius:6,color:C.white,fontSize:11,fontWeight:700,cursor:'pointer'}}>✓ Approve Release</button>
                      ) : (
                        <span style={{fontSize:10,color:C.gray,fontStyle:'italic'}}>Waiting on approval</span>
                      )}
                    </div>
                  )}

                  {(o.status==='Released'||o.status==='Partially Delivered') && (
                    <div style={{background:'#f9fbf9',borderRadius:8,padding:'10px 12px',marginBottom:8,fontSize:11,color:C.gray}}>
                      📦 Awaiting delivery — received by the Tool Keeper in Inventory's Receiving tab, not here.
                    </div>
                  )}

                  {canEdit && (o.status==='Delivered'||o.status==='Partially Delivered'||o.status==='Partially Invoiced') && (
                    <div style={{background:`${C.amber}0a`,borderRadius:8,padding:12,marginBottom:8}}>
                      <div style={{fontSize:9,fontWeight:800,color:C.gray,textTransform:'uppercase',marginBottom:8}}>Step 1 — Record Invoice (purchasing bookkeeping only) — {fmt(total-Number(o.amount_invoiced||0))} remaining</div>
                      <div style={{display:'grid',gridTemplateColumns:'1fr 1fr 1fr auto',gap:8,alignItems:'end'}}>
                        <div><label style={{fontSize:9,color:C.gray,fontWeight:700}}>Purchasing Ref #</label><input value={invoiceForm[o.id]?.invoice_number||''} onChange={e=>setInvoiceForm(p=>({...p,[o.id]:{...p[o.id],invoice_number:e.target.value.toUpperCase(),amount:p[o.id]?.amount||'',payment_terms:p[o.id]?.payment_terms||''}}))} onFocus={e=>e.target.select()} onBlur={e=>{if(!e.target.value.trim())setInvoiceForm(p=>({...p,[o.id]:{...p[o.id],invoice_number:'N/A',amount:p[o.id]?.amount||'',payment_terms:p[o.id]?.payment_terms||''}}))}} style={{...inputStyle,padding:'7px 9px'}}/></div>
                        <div><label style={{fontSize:9,color:C.gray,fontWeight:700}}>Amount</label><input type="number" defaultValue={total-Number(o.amount_invoiced||0)} onChange={e=>setInvoiceForm(p=>({...p,[o.id]:{...p[o.id],amount:e.target.value,invoice_number:p[o.id]?.invoice_number||'',payment_terms:p[o.id]?.payment_terms||''}}))} onFocus={e=>e.target.select()} onBlur={e=>{if(!e.target.value.trim()){e.target.value='0';setInvoiceForm(p=>({...p,[o.id]:{...p[o.id],amount:'0',invoice_number:p[o.id]?.invoice_number||'',payment_terms:p[o.id]?.payment_terms||''}}))}}} style={{...inputStyle,padding:'7px 9px'}}/></div>
                        <div><label style={{fontSize:9,color:C.gray,fontWeight:700}}>Payment Terms</label><input defaultValue={o.payment_terms||''} onChange={e=>setInvoiceForm(p=>({...p,[o.id]:{...p[o.id],payment_terms:e.target.value.toUpperCase(),invoice_number:p[o.id]?.invoice_number||'',amount:p[o.id]?.amount||''}}))} onFocus={e=>e.target.select()} onBlur={e=>{if(!e.target.value.trim()){e.target.value='N/A';setInvoiceForm(p=>({...p,[o.id]:{...p[o.id],payment_terms:'N/A',invoice_number:p[o.id]?.invoice_number||'',amount:p[o.id]?.amount||''}}))}}} style={{...inputStyle,padding:'7px 9px'}}/></div>
                        <button onClick={()=>recordInvoice(o)} style={{padding:'8px 16px',background:C.amber,border:'none',borderRadius:6,color:C.white,fontSize:11,fontWeight:700,cursor:'pointer'}}>Record Invoice</button>
                      </div>
                      <div style={{fontSize:9,color:C.gray,marginTop:6}}>This just confirms the invoice is in hand — it doesn't touch Accounting yet. That happens once it's marked Paid below, with the supplier's actual Sales Invoice Number.</div>
                    </div>
                  )}

                  {canEdit && (o.status==='Invoiced'||o.status==='Partially Invoiced'||o.status==='Partially Paid') && Number(o.amount_invoiced||0) > Number(o.amount_paid||0) && (
                    <div style={{background:`${C.accent}0a`,borderRadius:8,padding:12,marginBottom:8}}>
                      <div style={{fontSize:9,fontWeight:800,color:C.gray,textTransform:'uppercase',marginBottom:8}}>Step 2 — Mark as Paid (records to Accounting) — {fmt(Number(o.amount_invoiced||0)-Number(o.amount_paid||0))} remaining</div>
                      <div style={{display:'grid',gridTemplateColumns:'1fr 1fr 1fr auto',gap:8,alignItems:'end'}}>
                        <div><label style={{fontSize:9,color:C.gray,fontWeight:700}}>Sales Invoice # (from supplier) *</label><input value={payForm[o.id]?.sales_invoice_number||''} onChange={e=>setPayForm(p=>({...p,[o.id]:{...p[o.id],sales_invoice_number:e.target.value.toUpperCase(),amount:p[o.id]?.amount||'',payment_method:p[o.id]?.payment_method||'Cash'}}))} onFocus={e=>e.target.select()} style={{...inputStyle,padding:'7px 9px'}}/></div>
                        <div><label style={{fontSize:9,color:C.gray,fontWeight:700}}>Amount</label><input type="number" defaultValue={Number(o.amount_invoiced||0)-Number(o.amount_paid||0)} onChange={e=>setPayForm(p=>({...p,[o.id]:{...p[o.id],amount:e.target.value,sales_invoice_number:p[o.id]?.sales_invoice_number||'',payment_method:p[o.id]?.payment_method||'Cash'}}))} onFocus={e=>e.target.select()} onBlur={e=>{if(!e.target.value.trim()){e.target.value='0';setPayForm(p=>({...p,[o.id]:{...p[o.id],amount:'0',sales_invoice_number:p[o.id]?.sales_invoice_number||'',payment_method:p[o.id]?.payment_method||'Cash'}}))}}} style={{...inputStyle,padding:'7px 9px'}}/></div>
                        <div>
                          <label style={{fontSize:9,color:C.gray,fontWeight:700}}>Payment Method</label>
                          <select value={payForm[o.id]?.payment_method||'Cash'} onChange={e=>setPayForm(p=>({...p,[o.id]:{...p[o.id],payment_method:e.target.value,sales_invoice_number:p[o.id]?.sales_invoice_number||'',amount:p[o.id]?.amount||''}}))} style={{...inputStyle,padding:'7px 9px'}}>
                            {['Cash','Bank Transfer','GCash','Maya','Check'].map(m=><option key={m} value={m}>{m}</option>)}
                          </select>
                        </div>
                        <button onClick={()=>markPOPaid(o)} style={{padding:'8px 16px',background:C.accent,border:'none',borderRadius:6,color:C.white,fontSize:11,fontWeight:700,cursor:'pointer'}}>Mark Paid</button>
                      </div>
                      <div style={{fontSize:9,color:C.gray,marginTop:6}}>Required — this is what Accounting uses to close the account against.</div>
                    </div>
                  )}

                  {o.approved_by && (
                    <div style={{fontSize:10,color:C.gray,marginBottom:6}}>✓ Approved by {o.approved_by} on {new Date(o.approved_at).toLocaleDateString('en-PH')}</div>
                  )}

                  {o.status==='Paid' && (
                    <div style={{fontSize:11,color:C.accent,fontWeight:700}}>✓ Fully received, invoiced, and paid — {invoices.filter(iv=>iv.purchase_order_id===o.id&&iv.sales_invoice_number).map(iv=>`Sales Inv# ${iv.sales_invoice_number}`).join(', ')}</div>
                  )}
                  {o.status==='Invoiced' && (
                    <div style={{fontSize:11,color:C.amber,fontWeight:700}}>✓ Fully invoiced — awaiting payment to close with Accounting.</div>
                  )}
                </div>
              )
            })}
          {orderPageCount > 1 && (
            <div style={{display:'flex',justifyContent:'center',alignItems:'center',gap:10,marginTop:16}}>
              <button onClick={()=>setOrderPage(p=>Math.max(1,p-1))} disabled={currentOrderPage===1} style={{padding:'7px 14px',borderRadius:6,border:`1.5px solid ${C.lightGray}`,background:C.white,color:currentOrderPage===1?C.lightGray:C.dark,fontSize:11,fontWeight:700,cursor:currentOrderPage===1?'default':'pointer'}}>← Prev</button>
              <span style={{fontSize:11,fontWeight:700,color:C.gray}}>Page {currentOrderPage} of {orderPageCount}</span>
              <button onClick={()=>setOrderPage(p=>Math.min(orderPageCount,p+1))} disabled={currentOrderPage===orderPageCount} style={{padding:'7px 14px',borderRadius:6,border:`1.5px solid ${C.lightGray}`,background:C.white,color:currentOrderPage===orderPageCount?C.lightGray:C.dark,fontSize:11,fontWeight:700,cursor:currentOrderPage===orderPageCount?'default':'pointer'}}>Next →</button>
            </div>
          )}
          </>}
        </div>
      )}

      </>
      )}

      {/* ── NEW SUPPLIER MODAL ── */}
      {showSupModal && (
        <div style={{position:'fixed',inset:0,background:'rgba(0,0,0,0.6)',display:'flex',alignItems:'center',justifyContent:'center',zIndex:1200,padding:20}}>
          <div style={{background:'white',borderRadius:16,width:'100%',maxWidth:480,boxShadow:'0 25px 50px -12px rgba(0,0,0,0.5)'}}>
            <div style={{background:`linear-gradient(135deg, ${C.dark}, ${C.darkGreen})`,color:'white',padding:'18px 24px',display:'flex',justifyContent:'space-between'}}>
              <span style={{fontWeight:900,textTransform:'uppercase',letterSpacing:1}}>{selectedSup?'Edit':'New'} Supplier</span>
              <button onClick={()=>setShowSupModal(false)} style={{background:'none',border:'none',color:'white',cursor:'pointer',fontSize:18}}>✕</button>
            </div>
            <div style={{padding:24}}>
              <Field label="Supplier Name" value={supForm.name} onChange={(v:string)=>setSupForm(p=>({...p,name:v}))} />
              <Field label="Contact Person" value={supForm.contact_person} onChange={(v:string)=>setSupForm(p=>({...p,contact_person:v}))} />
              <div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:'0 14px'}}>
                <Field label="Phone" value={supForm.phone} onChange={(v:string)=>setSupForm(p=>({...p,phone:v}))} />
                <Field label="Email" value={supForm.email} onChange={(v:string)=>setSupForm(p=>({...p,email:v}))} />
              </div>
              <Field label="Address" value={supForm.address} onChange={(v:string)=>setSupForm(p=>({...p,address:v}))} />
              {error && <div style={{padding:10,background:`${C.red}12`,color:C.red,fontSize:12,marginBottom:15,borderRadius:6}}>{error}</div>}
              <div style={{display:'flex',gap:10,justifyContent:'flex-end'}}>
                <button onClick={()=>setShowSupModal(false)} style={{padding:'9px 18px',fontSize:11,fontWeight:800,letterSpacing:1,border:`1px solid ${C.accent}`,background:'transparent',color:C.accent,borderRadius:6,cursor:'pointer'}}>CANCEL</button>
                <button onClick={saveSupplier} disabled={saving} style={{padding:'10px 25px',background:C.accent,color:C.white,border:'none',borderRadius:8,fontWeight:800,cursor:'pointer',textTransform:'uppercase'}}>{saving?'SAVING...':'SAVE'}</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* ── NEW MATERIAL REQUEST MODAL ── */}
      {showNewReqModal && (
        <div style={{position:'fixed',inset:0,background:'rgba(0,0,0,0.6)',display:'flex',alignItems:'center',justifyContent:'center',zIndex:1200,padding:20}}>
          <div style={{background:'white',borderRadius:16,width:'100%',maxWidth:520,boxShadow:'0 25px 50px -12px rgba(0,0,0,0.5)'}}>
            <div style={{background:`linear-gradient(135deg, ${C.dark}, ${C.darkGreen})`,color:'white',padding:'18px 24px',display:'flex',justifyContent:'space-between'}}>
              <span style={{fontWeight:900,textTransform:'uppercase',letterSpacing:1}}>Log Material Request</span>
              <button onClick={()=>setShowNewReqModal(false)} style={{background:'none',border:'none',color:'white',cursor:'pointer',fontSize:18}}>✕</button>
            </div>
            <div style={{padding:24}}>
              <div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:'0 14px'}}>
                <Field label="Client PO Number" value={reqForm.po_number} onChange={(v:string)=>setReqForm(p=>({...p,po_number:v}))} />
                <Field label="Project Reference" value={reqForm.project_reference} onChange={(v:string)=>setReqForm(p=>({...p,project_reference:v}))} />
              </div>
              <Field label="Material Name" value={reqForm.material_name} onChange={(v:string)=>setReqForm(p=>({...p,material_name:v}))} />
              <div style={{display:'grid',gridTemplateColumns:'1fr 1fr 1fr',gap:'0 14px'}}>
                <Field label="Dimension" value={reqForm.dimension} onChange={(v:string)=>setReqForm(p=>({...p,dimension:v}))} />
                <Field label="Qty Needed" type="number" value={reqForm.qty_needed} onChange={(v:string)=>setReqForm(p=>({...p,qty_needed:v}))} />
                <Field label="Unit" type="select" value={reqForm.unit} onChange={(v:string)=>setReqForm(p=>({...p,unit:v}))} options={UNIT_OPTIONS} />
              </div>
              <Field label="Requested By" value={reqForm.requested_by} onChange={(v:string)=>setReqForm(p=>({...p,requested_by:v}))} />
              {error && <div style={{padding:10,background:`${C.red}12`,color:C.red,fontSize:12,marginBottom:15,borderRadius:6}}>{error}</div>}
              <div style={{display:'flex',gap:10,justifyContent:'flex-end'}}>
                <button onClick={()=>setShowNewReqModal(false)} style={{padding:'9px 18px',fontSize:11,fontWeight:800,letterSpacing:1,border:`1px solid ${C.accent}`,background:'transparent',color:C.accent,borderRadius:6,cursor:'pointer'}}>CANCEL</button>
                <button onClick={saveNewRequest} disabled={saving} style={{padding:'10px 25px',background:C.accent,color:C.white,border:'none',borderRadius:8,fontWeight:800,cursor:'pointer',textTransform:'uppercase'}}>{saving?'SAVING...':'LOG REQUEST'}</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}
